// delivery · кейсы dlv-02, dlv-03, dlv-04 (.qa/tests/delivery/) — полный цикл на своём заказе «QA-AUTO-delivery-e2e-…».
// СОЗДАЁТ ДАННЫЕ (не @prod-safe). Корзина buyer общая на сервере → не запускать параллельно с client-ordering / orders.
// Реальные заказы не трогаются. afterAll доводит заказ до «סופק» (или отклоняет, если он не утверждён).
// ВРЕМЕННЫЙ АДРЕС (решение пользователя 2026-10-03, вариант Б): у клиента «test» (аккаунт buyer) нет «כתובת משלוח».
// beforeAll запоминает исходное «כתובת מלאה» и ставит TEMP_ADDRESS; afterAll ВСЕГДА (try/finally, даже при падении)
// возвращает исходное значение. Другие поля клиента не трогаются. Авто-skip «нет адреса» убран.
// Находка n71 #6a70b0b7: водитель видит цены в תעודת משלוח → проверка «нет ₪» не автоматизирована (см. dlv-04).
import { test, expect, Page, Browser } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);
test.use({ storageState: auth('admin') });
test.describe.configure({ mode: 'serial' });

const ITEM = { id: '340b7b2b-e022-4f3b-a6f0-f9a3dc8ecfe8', name: 'מצית קליפט' };
const DRIVER = 'יוסי הנהג';
const OTHER_DRIVER = 'test נהג';
const order: { no?: string; id?: string } = {};
// Клиент «test» (аккаунт buyer) — /customers/<id>. Исходное «כתובת מלאה» (2026-10-03) — пусто.
const CUSTOMER_PATH = '/customers/a30f4767-3f86-4a49-a441-ecfd2faad6d0';
const TEMP_ADDRESS = 'QA-AUTO כתובת, רחוב בדיקה 1, תל אביב';
const customer: { originalAddress?: string } = {};

async function setCustomerAddress(browser: Browser, value: string | null): Promise<string> {
  const ctx = await browser.newContext({ storageState: auth('admin') });
  const page = await ctx.newPage();
  try {
    await page.goto(`${CUSTOMER_PATH}/edit`);
    await expect(page.getByRole('heading', { level: 1, name: 'עריכת לקוח' })).toBeVisible({ timeout: 20_000 });
    const field = page.getByRole('textbox', { name: 'כתובת מלאה' });
    await expect(field).toBeVisible();
    // дождаться, пока форма заполнится данными клиента (иначе прочитаем пустое «исходное» значение)
    await expect(page.getByRole('textbox', { name: /^שם עסק/ })).not.toHaveValue('', { timeout: 20_000 });
    const before = await field.inputValue();
    if (value !== null && before !== value) {
      await field.fill(value);
      await page.getByRole('button', { name: 'שמירה', exact: true }).click();
      await expect(page).toHaveURL(/\/customers$/, { timeout: 20_000 });
      await page.goto(`${CUSTOMER_PATH}/edit`);
      await expect(page.getByRole('textbox', { name: 'כתובת מלאה' })).toHaveValue(value, { timeout: 20_000 });
    }
    return before;
  } finally {
    await ctx.close();
  }
}

function isoDate(daysAhead: number) {
  const d = new Date(Date.now() + daysAhead * 86_400_000);
  return d.toISOString().slice(0, 10);
}
const he = (iso: string) => iso.split('-').reverse().join('.');

async function buyerPlaceOrder(browser: Browser, note: string): Promise<string> {
  const ctx = await browser.newContext({ storageState: auth('buyer') });
  const page = await ctx.newPage();
  await page.goto('/shop/cart');
  await expect(page.getByRole('heading', { name: 'העגלה שלי' })).toBeVisible();
  const remove = page.getByRole('button', { name: /^הסרה מהעגלה/ });
  // ждём, пока корзина загрузится (staging бывает медленным): либо есть позиции, либо «העגלה ריקה»
  await expect(remove.first().or(page.getByText('העגלה ריקה'))).toBeVisible({ timeout: 20_000 });
  while (await remove.count()) { await remove.first().click(); await page.waitForTimeout(500); }
  await page.goto(`/shop/p/${ITEM.id}`);
  await page.getByRole('button', { name: /^הוסף לעגלה/ }).click();
  await page.waitForTimeout(1000);
  await page.goto('/shop/cart');
  await expect(page.getByText(ITEM.name, { exact: true })).toBeVisible();
  await page.getByRole('button', { name: 'המשך לביצוע הזמנה' }).click();
  await page.getByRole('textbox', { name: 'הערות להזמנה' }).fill(note);
  await page.getByRole('button', { name: 'שליחת הזמנה' }).click();
  await expect(page.getByRole('heading', { name: 'ההזמנה נקלטה!' })).toBeVisible({ timeout: 20_000 });
  const no = (await page.getByText(/^#\d+$/).first().innerText()).match(/#(\d+)/)![1];
  await ctx.close();
  return no;
}

async function openOrder(page: Page) {
  if (order.id) { await page.goto(`/orders/${order.id}`); }
  else {
    await page.goto('/orders');
    await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
    await page.getByRole('button', { name: new RegExp(`^#${order.no} `) }).click();
    await expect(page).toHaveURL(/\/orders\/[0-9a-f-]{36}$/);
    order.id = page.url().split('/').pop();
  }
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${order.no}` })).toBeVisible({ timeout: 20_000 });
}
const shipCard = (page: Page) => page.getByRole('heading', { level: 3, name: 'משלוח' }).locator('xpath=ancestor::*[.//button[normalize-space()="שמירת שיבוץ"]][1]');

async function impersonate(page: Page, employee: string) {
  await page.goto('/team');
  await expect(page.getByRole('heading', { name: 'צוות והרשאות' })).toBeVisible({ timeout: 20_000 });
  const row = page.locator('div').filter({ hasText: employee }).filter({ has: page.getByRole('button', { name: 'פעולות' }) }).last();
  await row.getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: 'כניסה כעובד' }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'כניסה', exact: true }).click();
  await expect(page.getByText(`מחובר/ת כרגע בתור ${employee} — כניסה כעובד פעילה`)).toBeVisible({ timeout: 20_000 });
}
async function backToAdmin(page: Page) {
  await page.getByRole('button', { name: 'חזרה לחשבון הניהול' }).click();
  await expect(page.getByText('מפיץ ראשי').first()).toBeVisible({ timeout: 20_000 });
}

test.describe('delivery — מחזור שיוך נהג על הזמנת QA-AUTO', () => {
  test.beforeAll(async ({ browser }) => {
    test.setTimeout(180_000);
    customer.originalAddress = await setCustomerAddress(browser, null); // запомнить исходное
    await setCustomerAddress(browser, TEMP_ADDRESS);
    order.no = await buyerPlaceOrder(browser, `QA-AUTO-delivery-e2e-${Date.now()}`);
  });

  test.afterAll(async ({ browser }) => {
    test.setTimeout(180_000);
    try {
      await finishOrder(browser);
    } finally {
      // вернуть клиента «test» в исходное состояние — даже если заказ/тесты упали
      if (customer.originalAddress !== undefined) await setCustomerAddress(browser, customer.originalAddress);
    }
  });

  async function finishOrder(browser: Browser) {
    if (!order.no) return;
    const ctx = await browser.newContext({ storageState: auth('admin') });
    const page = await ctx.newPage();
    await openOrder(page);
    if (await page.getByRole('button', { name: 'דחייה' }).count()) {
      await page.getByRole('button', { name: 'דחייה' }).click();
      await page.getByRole('dialog').getByRole('textbox', { name: 'סיבת הדחייה *' }).fill('QA-AUTO cleanup');
      await page.getByRole('dialog').getByRole('button', { name: 'דחה הזמנה' }).click();
    } else {
      for (const b of ['סמן כמוכנה למשלוח', 'סמן כיצאה למשלוח', 'סמן כסופקה']) {
        const btn = shipCard(page).getByRole('button', { name: b });
        if (await btn.count() && await btn.isEnabled()) { await btn.click(); await expect(btn).toHaveCount(0, { timeout: 20_000 }); }
      }
      // при назначенном водителе «יצאה למשלוח» / «סימון כסופקה» делает только водитель (у admin кнопки нет) — доводим через него
      if (!(await shipCard(page).getByText('סופקה', { exact: true }).count())) {
        await impersonate(page, DRIVER);
        await page.goto('/delivery');
        await page.getByRole('link', { name: `תעודת משלוח · הזמנה #${order.no}` }).click();
        const out = page.getByRole('button', { name: /יצאה למשלוח/ });
        if (await out.count()) { await out.click(); await expect(out).toHaveCount(0, { timeout: 20_000 }); }
        const done = page.getByRole('button', { name: /סימון כסופקה/ });
        if (await done.count()) { await done.click(); await expect(done).toHaveCount(0, { timeout: 20_000 }); }
        await backToAdmin(page);
        await openOrder(page);
      }
      await expect(shipCard(page)).toContainText('סופקה', { timeout: 20_000 });
    }
    await ctx.close();
  }

  test('לפני אישור — שיוך חסום; אחרי אישור — נהג + תאריך אספקה נשמרים («השיבוץ נשמר») #6a7491c7 @desktop', async ({ page }) => {
    await openOrder(page);
    const card = shipCard(page);
    await expect(card.getByRole('combobox', { name: 'נהג' })).toBeDisabled();
    await expect(card.getByRole('textbox', { name: 'תאריך אספקה' })).toBeDisabled();
    await expect(card.getByText('ההזמנה טרם אושרה')).toBeVisible();

    await page.getByRole('button', { name: 'אישור הזמנה' }).click();
    await page.getByRole('dialog').getByRole('button', { name: 'אשר הזמנה' }).click();
    await expect(card).toContainText('ממתינה לליקוט', { timeout: 20_000 });

    await expect(card.getByText('ללקוח אין כתובת משלוח')).toHaveCount(0); // адрес временно добавлен в beforeAll

    const date = isoDate(3);
    await card.getByRole('combobox', { name: 'נהג' }).selectOption({ label: DRIVER });
    await card.getByRole('textbox', { name: 'תאריך אספקה' }).fill(date);
    await card.getByRole('button', { name: 'שמירת שיבוץ' }).click();
    await expect(page.getByText('השיבוץ נשמר')).toBeVisible();
    await expect(card).toContainText('ממתינה לליקוט'); // статус не меняется
    await page.reload();
    await expect(shipCard(page).getByRole('combobox', { name: 'נהג' })).toHaveValue(/.+/);
    await expect(shipCard(page).getByRole('combobox', { name: 'נהג' }).locator('option:checked')).toHaveText(DRIVER);
    await expect(shipCard(page).getByRole('textbox', { name: 'תאריך אספקה' })).toHaveValue(date);

    await shipCard(page).getByRole('button', { name: 'סמן כמוכנה למשלוח' }).click();
    // ждём сохранения статуса: «מוכנה למשלוח» есть и в подписи самой кнопки, поэтому ждём исчезновения кнопки и текст статуса
    await expect(shipCard(page).getByRole('button', { name: 'סמן כמוכנה למשלוח' })).toHaveCount(0, { timeout: 20_000 });
    await expect(shipCard(page)).toContainText('ההזמנה ארוזה וממתינה ליציאת הנהג', { timeout: 20_000 });
    await page.goto('/delivery');
    const link = page.getByRole('link', { name: `תעודת משלוח · הזמנה #${order.no}` });
    await expect(link.locator('..')).toContainText(`אספקה: ${he(date)}`);
    await expect(link.locator('..')).toContainText(DRIVER);
  });

  test('נהג: לחיצה על ההזמנה פותחת תעודת משלוח (פרטי משלוח, טלפון, מפה), «יצא למשלוח» מהתעודה #6a70b0b7 @desktop', async ({ page }) => {
    await impersonate(page, DRIVER);
    await expect(page.getByText('הפריטים במשלוח')).toHaveCount(0);
    await page.getByRole('link', { name: `תעודת משלוח · הזמנה #${order.no}` }).click();
    await expect(page.getByRole('heading', { level: 1, name: `תעודת משלוח · הזמנה #${order.no}` })).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText('פרטי משלוח')).toBeVisible();
    await expect(page.getByText(/איש קשר/).first()).toBeVisible();
    await expect(page.locator('a[href^="tel:"]').first()).toBeVisible();
    await expect(page.locator('a[href*="google.com/maps"]').first()).toBeVisible();
    await expect(page.getByRole('cell', { name: ITEM.name })).toBeVisible();
    // НЕ проверяем «нет ₪»: находка n71 (2026-10-03) — водитель видит מחיר יחידה / סה״כ / סה"כ לתשלום.
    await page.getByRole('button', { name: /יצאה למשלוח/ }).click();
    await expect(page.getByText('בדרך ללקוח').first()).toBeVisible({ timeout: 20_000 });
    await backToAdmin(page);
  });

  test('מפיץ מחליף נהג, מסלול ותאריך אחרי «בדרך ללקוח» מתעודת המשלוח #6a70b080 @desktop', async ({ page }) => {
    await page.goto(`/delivery/${order.id}`);
    await expect(page.getByText('בדרך ללקוח').first()).toBeVisible({ timeout: 20_000 });
    const date = isoDate(4);
    await page.getByRole('combobox', { name: 'נהג' }).selectOption({ label: OTHER_DRIVER });
    await page.getByRole('combobox', { name: 'מסלול חלוקה' }).fill('QA-AUTO-route');
    await page.getByRole('textbox', { name: 'תאריך אספקה' }).fill(date);
    await page.getByRole('button', { name: 'שייך ושלח לנהג' }).click();
    await page.waitForTimeout(1500);
    await page.reload();
    await expect(page.getByText(`נהג: ${OTHER_DRIVER}`)).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText(`תאריך אספקה: ${he(date)}`).first()).toBeVisible();
    await expect(page.getByText('בדרך ללקוח').first()).toBeVisible();
  });
});
